// 知らせるだけ：手続きが済んだという事実だけ
notification = {
  "type": "配送先の変更が受理された",
  "shipment-id": "01b9a761",
  "payload": { "details": "/01b9a761/address-change" }
};

// 状態を運ぶ：変わった値そのもの
stateTransfer = {
  "type": "配送先が変わった",
  "shipment-id": "01b9a761",
  "payload": { "new-address": "北山市中央3-1" }
};

// 業務イベント：業務として何が起きたかの要点
domainEvent = {
  "type": "荷主が届け先を変更した",
  "shipment-id": "01b9a761",
  "payload": { "rerouted-after-dispatch": true }
};
